-- Menambahkan kolom deskripsi pada setiap item menu (menu_items)
-- agar pengguna dapat melihat penjelasan singkat hidangan di halaman detail tenant.

alter table public.menu_items
  add column if not exists description text check (description is null or char_length(description) <= 300);

update public.menu_items as m
set description = v.description
from (
  values
